package ai.cineforge.gpu;
import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class MainActivity extends Activity { EditText endpoint,prompt; TextView status; Button connect,render; ExecutorService worker=Executors.newSingleThreadExecutor();
String base(){String s=endpoint.getText().toString().trim();while(s.endsWith("/"))s=s.substring(0,s.length()-1);return s;}
String request(String url,String method,String body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setConnectTimeout(8000);c.setReadTimeout(12000);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.getOutputStream().write(body.getBytes("UTF-8"));}int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]buf=new byte[1024];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);c.disconnect();return out.toString("UTF-8");}
void run(String msg,Callable<String> task){status.setText(msg);worker.submit(()->{try{String r=task.call();runOnUiThread(()->status.setText(r));}catch(Exception e){runOnUiThread(()->status.setText("Error: "+e.getMessage()));}});}
public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,32,28,24);root.setBackgroundColor(Color.rgb(12,18,32));TextView title=new TextView(this);title.setText("CineForge GPU Companion");title.setTextSize(24);title.setTextColor(Color.WHITE);root.addView(title);TextView info=new TextView(this);info.setText("Connect to your own GPU host. Inference must be installed on that host.");info.setTextColor(Color.LTGRAY);info.setPadding(0,20,0,20);root.addView(info);endpoint=new EditText(this);endpoint.setSingleLine();endpoint.setHint("GPU host URL");endpoint.setText("http://10.0.2.2:8000");endpoint.setTextColor(Color.WHITE);endpoint.setHintTextColor(Color.GRAY);root.addView(endpoint);connect=new Button(this);connect.setText("Check GPU host");root.addView(connect);status=new TextView(this);status.setText("Disconnected");status.setTextColor(Color.YELLOW);status.setPadding(0,16,0,16);root.addView(status);prompt=new EditText(this);prompt.setHint("Describe your video");prompt.setMinLines(4);prompt.setGravity(Gravity.TOP);prompt.setTextColor(Color.WHITE);prompt.setHintTextColor(Color.GRAY);root.addView(prompt);render=new Button(this);render.setText("Submit render request");root.addView(render);connect.setOnClickListener(v->run("Checking host…",()->{JSONObject j=new JSONObject(request(base()+"/api/mobile/health","GET",null));return "Host: "+j.optString("status")+"\nGPU: "+j.optString("gpu","unknown")+"\nInference: "+j.optString("inference","unknown");}));render.setOnClickListener(v->{String p=prompt.getText().toString().trim();if(p.isEmpty()){status.setText("Enter a video prompt first.");return;}run("Submitting…",()->{JSONObject q=new JSONObject();q.put("prompt",p);JSONObject j=new JSONObject(request(base()+"/api/mobile/render","POST",q.toString()));return j.optString("message",j.toString());});});setContentView(root);}
public void onDestroy(){worker.shutdown();super.onDestroy();}
}